void ShellSort(DataType a[], int n, int d[], int numOfD)
{ int i, j, k, m, span;
  DataType temp;
  for(m = 0; m < numOfD; m++) {
           span = d[m];
                  for(k = 0; k < span; k++) {
              for(i = k; i < n-span; i = i+span) {
                  temp = a[i+span]; j = i;
                  while(j > -1 && temp.key <= a[j].key) {
                          a[j+span] = a[j]; j = j-span; }
                  a[j+span] = temp;              }
                                         }
  } }                                                   11

