void SelectSort(DataType a[], int n)
{   int i, j, small; DataType temp;
    for(i = 0; i < n-1; i++)
    {     small = i;
              for(j = i+1;j<n;j++)
         if(a[j].key < a[small].key) small=j;
         if(small != i){ temp = a[i];
                            a[i] = a[small];
                            a[small] = temp;
                        }
     }
}                                               16

